package api

import (
	"context"
	"fmt"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/block/schemabot/pkg/auth"
	"github.com/block/schemabot/pkg/state"
	"github.com/block/schemabot/pkg/storage"
)

// sweepPlanStore serves the sweep's stored-plan resolutions: Get resolves the
// apply path's plan lookup, GetByID resolves the rollback source plan.
type sweepPlanStore struct {
	mockPlanLookupStore
	byID *storage.Plan
}

func (s *sweepPlanStore) GetByID(context.Context, int64) (*storage.Plan, error) {
	return s.byID, nil
}

// staticTaskStore returns a fixed task list for any database.
type staticTaskStore struct {
	storage.TaskStore
	tasks []*storage.Task
}

func (s *staticTaskStore) GetByDatabase(context.Context, string) ([]*storage.Task, error) {
	return s.tasks, nil
}

// The forward-auth middleware admits every operator-group member to every
// write-tier route before the target database is known, so per-database scope
// exists only if each mutating handler individually re-establishes it. This
// sweep walks the service's complete route table with the same tier rule the
// middleware applies, drives every write-tier route as a scoped operator whose
// grant does not cover the fixture's target, and requires a 403. A mutating
// route without a fixture fails the sweep — a new endpoint cannot ship until
// it proves it denies scoped operators by default.
func TestMutatingRoutesDenyScopedOperatorByDefault(t *testing.T) {
	// Every stored object resolves to the orders database, which the
	// payments-team operator's grant does not cover. The rollback source
	// chain (completed apply -> plan with captured original files -> latest
	// completed task) is fully consistent so the rollback route reaches its
	// authorization check rather than failing input validation first.
	sourcePlan := &storage.Plan{
		ID:          7,
		Database:    "orders",
		Environment: "staging",
		Namespaces: map[string]*storage.NamespacePlanData{
			"orders": {OriginalFilesCaptured: true},
		},
	}
	apply := &storage.Apply{
		ID:              42,
		ApplyIdentifier: "apply-1",
		Database:        "orders",
		DatabaseType:    "mysql",
		Environment:     "staging",
		State:           state.Apply.Completed,
		PlanID:          7,
	}
	task := &storage.Task{
		ApplyID:      42,
		PlanID:       7,
		Database:     "orders",
		DatabaseType: "mysql",
		Environment:  "staging",
		State:        state.Task.Completed,
	}
	st := &mockStorageWithApplyStores{
		plans: &sweepPlanStore{
			mockPlanLookupStore: mockPlanLookupStore{plan: &storage.Plan{
				PlanIdentifier: "plan-1",
				Database:       "orders",
				Environment:    "staging",
			}},
			byID: sourcePlan,
		},
		applies: &staticApplyStore{apply: apply},
		tasks:   &staticTaskStore{tasks: []*storage.Task{task}},
		locks:   &recordingLockStore{},
	}

	controlBody := `{"apply_id":"apply-1","environment":"staging"}`
	lockBody := `{"database":"orders","database_type":"mysql","owner":"sweep"}`
	fixtures := map[string]string{
		"POST /api/plan":              `{"database":"orders","environment":"staging","type":"mysql","schema_files":{"default":{"files":{"t.sql":"CREATE TABLE t (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY)"}}}}`,
		"POST /api/apply":             `{"plan_id":"plan-1","environment":"staging"}`,
		"POST /api/cutover":           controlBody,
		"POST /api/stop":              controlBody,
		"POST /api/cancel":            controlBody,
		"POST /api/start":             controlBody,
		"POST /api/release":           controlBody,
		"POST /api/revert":            controlBody,
		"POST /api/skip-revert":       controlBody,
		"POST /api/rollback/plan":     controlBody,
		"POST /api/locks/acquire":     lockBody,
		"DELETE /api/locks":           lockBody,
		"POST /api/settings":          `{"key":"pause_applies","value":"true"}`,
		"POST /api/checks/scan":       `{}`,
		"POST /api/checks/synthesize": `{}`,
		"POST /api/checks/repos":      `{}`,
		"POST /api/webhooks/redrive":  `{}`,
		// The storage schema routes take no database — they are about
		// SchemaBot's own bookkeeping database — so a scoped operator is denied
		// on the admin requirement itself rather than on a target outside their
		// grant.
		"POST /api/storage/schema/plan":  `{}`,
		"POST /api/storage/schema/apply": `{}`,
	}

	svc := New(st, scopedWriteConfig(), nil, slog.New(slog.DiscardHandler))
	mux := http.NewServeMux()
	svc.ConfigureRoutes(mux)
	operator := &auth.User{Subject: "bob", Groups: []string{"payments-team"}}

	used := make(map[string]bool)
	for _, route := range svc.apiRoutes() {
		method, path, found := strings.Cut(route.pattern, " ")
		require.Truef(t, found, "route pattern %q must be METHOD /path", route.pattern)
		if auth.TierForRequest(method, path) == auth.TierRead {
			continue
		}

		t.Run(fmt.Sprintf("%s %s", method, path), func(t *testing.T) {
			body, ok := fixtures[route.pattern]
			require.Truef(t, ok,
				"mutating route %q has no scoped-operator denial fixture: add one here and ensure the handler enforces an authorizeDirect* check before mutating anything",
				route.pattern)
			used[route.pattern] = true

			ctx := auth.WithUser(t.Context(), operator)
			req := httptest.NewRequestWithContext(ctx, method, path, strings.NewReader(body))
			rec := httptest.NewRecorder()
			mux.ServeHTTP(rec, req)

			assert.Equalf(t, http.StatusForbidden, rec.Code,
				"a scoped operator outside their grant must be denied with 403; got %d body %q", rec.Code, rec.Body.String())
		})
	}

	for pattern := range fixtures {
		assert.Truef(t, used[pattern], "fixture %q matches no registered mutating route; remove it", pattern)
	}
}

package api_test

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/block/schemabot/pkg/api"
)

func TestAuthConfigValidate(t *testing.T) {
	t.Run("empty type is valid", func(t *testing.T) {
		require.NoError(t, (&api.AuthConfig{}).Validate())
	})

	t.Run("none type is valid", func(t *testing.T) {
		require.NoError(t, (&api.AuthConfig{Type: "none"}).Validate())
	})

	t.Run("unknown type is rejected", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "ldap"}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "unknown auth type")
	})

	t.Run("oidc requires issuer", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "oidc"}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "issuer")
	})

	t.Run("oidc with issuer and audience is valid", func(t *testing.T) {
		require.NoError(t, (&api.AuthConfig{Type: "oidc", Issuer: "https://issuer.example.com", Audience: "schemabot"}).Validate())
	})

	t.Run("oidc requires audience", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "oidc", Issuer: "https://issuer.example.com"}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "audience")
	})

	t.Run("oidc whitespace-only issuer is rejected", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "oidc", Issuer: "   "}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "issuer")
	})

	t.Run("oidc issuer with surrounding whitespace is rejected", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "oidc", Issuer: " https://issuer.example.com "}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "whitespace")
	})

	t.Run("unknown type message lists forward_auth", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "ldap"}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "forward_auth")
	})

	t.Run("forward_auth requires a trust anchor", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "forward_auth"}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "trust anchor")
	})

	t.Run("forward_auth spiffe-only is valid", func(t *testing.T) {
		require.NoError(t, (&api.AuthConfig{Type: "forward_auth", ForwardAuth: api.ForwardAuthSettings{
			TrustedProxySPIFFE: []string{"spiffe://example.org/ns/ingress/sa/proxy"},
			WriteGroups:        []string{"owners"},
		}}).Validate())
	})

	t.Run("forward_auth rejects a malformed cidr", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "forward_auth", ForwardAuth: api.ForwardAuthSettings{
			TrustedProxyCIDRs: []string{"not-a-cidr"},
		}}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "CIDR")
	})

	t.Run("forward_auth with a cidr is valid", func(t *testing.T) {
		require.NoError(t, (&api.AuthConfig{Type: "forward_auth", ForwardAuth: api.ForwardAuthSettings{
			TrustedProxyCIDRs: []string{"127.0.0.1/32"},
			WriteGroups:       []string{"owners"},
		}}).Validate())
	})

	t.Run("forward_auth with spiffe and a cidr is valid", func(t *testing.T) {
		require.NoError(t, (&api.AuthConfig{Type: "forward_auth", ForwardAuth: api.ForwardAuthSettings{
			TrustedProxyCIDRs:  []string{"127.0.0.1/32"},
			TrustedProxySPIFFE: []string{"spiffe://example.org/ns/ingress/sa/proxy"},
			WriteGroups:        []string{"owners"},
		}}).Validate())
	})

	t.Run("forward_auth with gateway and service callers is valid", func(t *testing.T) {
		require.NoError(t, (&api.AuthConfig{Type: "forward_auth", ForwardAuth: api.ForwardAuthSettings{
			TrustedProxySPIFFE:   []string{"spiffe://example.org/ns/ingress/sa/proxy"},
			WriteGroups:          []string{"owners"},
			TrustedGatewaySPIFFE: []string{"spiffe://example.org/ns/service-ingress/sa/gateway"},
			ReadServiceSPIFFE:    []string{"spiffe://example.org/ns/reporting/sa/reporting"},
		}}).Validate())
	})

	t.Run("forward_auth gateway requires service callers", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "forward_auth", ForwardAuth: api.ForwardAuthSettings{
			TrustedProxySPIFFE:   []string{"spiffe://example.org/ns/ingress/sa/proxy"},
			TrustedGatewaySPIFFE: []string{"spiffe://example.org/ns/service-ingress/sa/gateway"},
		}}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "read_service_spiffe")
	})

	t.Run("forward_auth service callers require a gateway", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "forward_auth", ForwardAuth: api.ForwardAuthSettings{
			TrustedProxySPIFFE: []string{"spiffe://example.org/ns/ingress/sa/proxy"},
			ReadServiceSPIFFE:  []string{"spiffe://example.org/ns/reporting/sa/reporting"},
		}}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "trusted_gateway_spiffe")
	})

	t.Run("forward_auth caller header with surrounding whitespace is rejected", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "forward_auth", ForwardAuth: api.ForwardAuthSettings{
			TrustedProxySPIFFE:   []string{"spiffe://example.org/ns/ingress/sa/proxy"},
			TrustedGatewaySPIFFE: []string{"spiffe://example.org/ns/service-ingress/sa/gateway"},
			ReadServiceSPIFFE:    []string{"spiffe://example.org/ns/reporting/sa/reporting"},
			CallerSPIFFEHeader:   " X-Forwarded-Caller-Spiffe-Id ",
		}}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "whitespace")
	})

	t.Run("forward_auth rejects proxy/gateway spiffe overlap", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "forward_auth", ForwardAuth: api.ForwardAuthSettings{
			TrustedProxySPIFFE:   []string{"spiffe://example.org/ns/ingress/sa/proxy"},
			TrustedGatewaySPIFFE: []string{"spiffe://example.org/ns/ingress/sa/proxy"},
			ReadServiceSPIFFE:    []string{"spiffe://example.org/ns/reporting/sa/reporting"},
		}}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "both trusted_proxy_spiffe and trusted_gateway_spiffe")
	})

	t.Run("forward_auth rejects the gateway lane under CIDR-only proxy trust", func(t *testing.T) {
		err := (&api.AuthConfig{Type: "forward_auth", ForwardAuth: api.ForwardAuthSettings{
			TrustedProxyCIDRs:    []string{"127.0.0.1/32"},
			TrustedGatewaySPIFFE: []string{"spiffe://example.org/ns/service-ingress/sa/gateway"},
			ReadServiceSPIFFE:    []string{"spiffe://example.org/ns/reporting/sa/reporting"},
		}}).Validate()
		require.Error(t, err)
		assert.Contains(t, err.Error(), "SPIFFE-anchored proxy trust")
	})
}

package api

import (
	"log/slog"
	"net/http"
	"testing"

	"github.com/block/schemabot/pkg/auth"
	"github.com/block/schemabot/pkg/metrics"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	sdkmetric "go.opentelemetry.io/otel/sdk/metric"
	"go.opentelemetry.io/otel/sdk/metric/metricdata"
)

// installManualMetricReader routes the global meter provider through a manual
// reader for the duration of the test so recorded counters can be inspected.
func installManualMetricReader(t *testing.T) *sdkmetric.ManualReader {
	t.Helper()
	reader := sdkmetric.NewManualReader()
	mp := sdkmetric.NewMeterProvider(sdkmetric.WithReader(reader))
	prevMP := otel.GetMeterProvider()
	otel.SetMeterProvider(mp)
	t.Cleanup(func() {
		otel.SetMeterProvider(prevMP)
		require.NoError(t, mp.Shutdown(t.Context()))
	})
	return reader
}

// collectCounterPoints returns the data points recorded so far for one counter.
func collectCounterPoints(t *testing.T, reader *sdkmetric.ManualReader, name string) []metricdata.DataPoint[int64] {
	t.Helper()
	var rm metricdata.ResourceMetrics
	require.NoError(t, reader.Collect(t.Context(), &rm))
	for _, sm := range rm.ScopeMetrics {
		for _, m := range sm.Metrics {
			if m.Name != name {
				continue
			}
			sum, ok := m.Data.(metricdata.Sum[int64])
			require.True(t, ok, "%s is not an int64 sum", name)
			return sum.DataPoints
		}
	}
	return nil
}

func attributeValue(t *testing.T, dp metricdata.DataPoint[int64], key string) string {
	t.Helper()
	v, ok := dp.Attributes.Value(attribute.Key(key))
	require.True(t, ok, "attribute %q missing", key)
	return v.AsString()
}

// Every actor-authorization reason the PR command door can produce must be
// recorded under its own name. A reason the metric does not recognize is
// collapsed to "unknown", which would hide which principal granted a command
// or why it was blocked.
func TestPRCommandActorAuthorizationReasonsRecordAsThemselves(t *testing.T) {
	reasons := []string{
		ActorAuthReasonDisabled,
		ActorAuthReasonAllowedAdminTeam,
		ActorAuthReasonAllowedAdminUser,
		ActorAuthReasonAllowedRepoAdminTeam,
		ActorAuthReasonAllowedRepoAdminUser,
		ActorAuthReasonAllowedOperatorTeam,
		ActorAuthReasonAllowedOperatorUser,
		ActorAuthReasonMissingActor,
		ActorAuthReasonMissingServerConfig,
		ActorAuthReasonMissingDatabaseConfig,
		ActorAuthReasonNoConfiguredPrincipal,
		ActorAuthReasonNotAuthorized,
		ActorAuthReasonGitHubError,
	}
	reader := installManualMetricReader(t)
	for _, reason := range reasons {
		metrics.RecordPRCommandActorAuthorization(t.Context(), "apply", "mydb", "staging", "org/repo", "allowed", reason)
	}

	recorded := map[string]bool{}
	for _, dp := range collectCounterPoints(t, reader, "schemabot.pr_command_actor_authorization.total") {
		recorded[attributeValue(t, dp, "reason")] = true
	}
	for _, reason := range reasons {
		assert.True(t, recorded[reason], "reason %q was not recorded under its own name", reason)
	}
	assert.False(t, recorded[ActorAuthReasonUnknown], "no reason in the vocabulary collapsed to unknown")
}

// A direct write whose stored plan cannot be loaded never authorizes, and the
// decision still lands on the metric: status skipped with the target_unresolved
// reason, so a run of storage failures on the authorization path is countable
// rather than visible only in the logs.
func TestUnresolvedDirectWriteTargetIsCountedAsSkipped(t *testing.T) {
	logger := slog.New(slog.DiscardHandler)
	operator := &auth.User{Subject: "bob", Groups: []string{"payments-team"}}

	cases := map[string]struct {
		plans      *mockPlanLookupStore
		wantStatus int
	}{
		"plan lookup fails":   {plans: &mockPlanLookupStore{err: assert.AnError}, wantStatus: http.StatusInternalServerError},
		"plan does not exist": {plans: &mockPlanLookupStore{}, wantStatus: http.StatusNotFound},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			reader := installManualMetricReader(t)
			svc := New(&mockStorageWithPlanLookup{plans: tc.plans}, scopedWriteConfig(), nil, logger)
			rec := scopedDenialRequest(t, svc.handleApply, operator, http.MethodPost, "/api/apply",
				`{"plan_id":"plan-1","environment":"staging"}`)
			require.Equal(t, tc.wantStatus, rec.Code)

			points := collectCounterPoints(t, reader, "schemabot.direct_write_authorization.total")
			require.Len(t, points, 1, "exactly one direct-write decision is recorded")
			assert.Equal(t, "apply", attributeValue(t, points[0], "operation"))
			assert.Equal(t, "skipped", attributeValue(t, points[0], "status"))
			assert.Equal(t, DirectWriteReasonTargetUnresolved, attributeValue(t, points[0], "reason"))
			assert.Equal(t, "staging", attributeValue(t, points[0], "environment"))
			assert.Equal(t, "unknown", attributeValue(t, points[0], "database"),
				"no target resolved, so the database attribute carries the sentinel")
		})
	}
}

//go:build integration

package api

import (
	"database/sql"
	"errors"
	"log/slog"
	"os"
	"testing"
	"time"

	_ "github.com/block/mysql"
	"github.com/block/spirit/pkg/utils"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/block/schemabot/pkg/auth"
	"github.com/block/schemabot/pkg/state"
	"github.com/block/schemabot/pkg/storage"
	"github.com/block/schemabot/pkg/storage/mysqlstore"
	"github.com/block/schemabot/pkg/tern"
)

// A data-plane host queues control-plane-authorized dispatches through
// EnqueueAuthorizedApply against real storage. The queued apply must be durable (apply,
// task, and operation rows committed in one transaction), claimable by an
// operator driver, and covered by the one-active-apply-per-target invariant —
// while the gated ExecuteApply path on the same service keeps failing closed
// because the deployment has no database config to evaluate source policy
// against.
func TestEnqueueAuthorizedApplyQueuesDurableApplyAgainstStorage(t *testing.T) {
	ctx := t.Context()

	dsn := newStorageDatabaseWithSchema(t).DSN
	logger := slog.New(slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelError}))

	db, err := sql.Open("block-mysql", dsn)
	require.NoError(t, err, "failed to open database")
	require.NoError(t, db.PingContext(ctx), "failed to ping database")
	t.Cleanup(func() { utils.CloseAndLog(db) })

	stor := mysqlstore.New(db)

	plan := &storage.Plan{
		PlanIdentifier: "plan-enqueue-integration",
		Database:       "testdb",
		DatabaseType:   storage.DatabaseTypeMySQL,
		Deployment:     "default",
		Target:         "testdb-staging-target",
		Repository:     "octocat/hello-world",
		PullRequest:    1,
		SchemaPath:     "schema/testdb",
		Environment:    "staging",
		Namespaces: map[string]*storage.NamespacePlanData{
			"testdb": {
				Tables: []storage.TableChange{
					{
						Namespace: "testdb",
						Table:     "users",
						DDL:       "ALTER TABLE users ADD COLUMN email varchar(255)",
						Operation: "alter",
					},
				},
			},
		},
		CreatedAt: time.Now(),
	}
	_, err = stor.Plans().Create(ctx, plan)
	require.NoError(t, err, "failed to store trusted plan")

	cfg := &ServerConfig{
		TernDeployments: TernConfig{
			"default": {"staging": "localhost:9090"},
		},
	}
	mockClient := &mockTernClient{isRemote: true}
	svc := New(stor, cfg, map[string]tern.Client{"default/staging": mockClient}, logger)

	// The gated path fails closed: this deployment has no database config to
	// evaluate the trusted plan's source against.
	_, _, err = svc.ExecuteApply(ctx, ApplyRequest{
		PlanID:      plan.PlanIdentifier,
		Environment: "staging",
	})
	var policyErr *SourcePolicyError
	require.True(t, errors.As(err, &policyErr), "ExecuteApply must fail closed without database config")
	assert.Equal(t, SourcePolicyReasonMissingDatabaseConfig, policyErr.Reason)

	resp, applyID, err := svc.EnqueueAuthorizedApply(ctx, ApplyRequest{
		PlanID:      plan.PlanIdentifier,
		Environment: "staging",
		Caller:      "control-plane",
	})
	require.NoError(t, err)
	require.NotNil(t, resp)
	require.True(t, resp.Accepted)
	require.Positive(t, applyID)

	apply, err := stor.Applies().Get(ctx, applyID)
	require.NoError(t, err)
	require.NotNil(t, apply)
	assert.Equal(t, state.Apply.Pending, apply.State)
	assert.Equal(t, "testdb", apply.Database)
	assert.Equal(t, "staging", apply.Environment)
	assert.Equal(t, "default", apply.Deployment)
	assert.Equal(t, "testdb-staging-target", apply.GetOptions().Target)
	assert.Equal(t, resp.ApplyID, apply.ApplyIdentifier)

	tasks, err := stor.Tasks().GetByApplyID(ctx, applyID)
	require.NoError(t, err)
	require.Len(t, tasks, 1)
	assert.Equal(t, state.Task.Pending, tasks[0].State)
	assert.Equal(t, "users", tasks[0].TableName)
	assert.Contains(t, tasks[0].DDL, "ADD COLUMN")
	assert.Contains(t, tasks[0].DDL, "email")

	operations, err := stor.ApplyOperations().ListByApply(ctx, applyID)
	require.NoError(t, err)
	require.Len(t, operations, 1)
	assert.Equal(t, "default", operations[0].Deployment)
	assert.Equal(t, "testdb-staging-target", operations[0].Target)

	// One active apply per target: a second dispatch is rejected while the
	// first is still pending.
	_, _, err = svc.EnqueueAuthorizedApply(ctx, ApplyRequest{
		PlanID:      plan.PlanIdentifier,
		Environment: "staging",
	})
	require.ErrorIs(t, err, storage.ErrActiveApplyExists)

	// The committed apply, task, and operation rows make the queued apply
	// claimable by an operator driver.
	claimed, err := stor.ApplyOperations().FindNextApplyOperation(ctx, "driver-test")
	require.NoError(t, err)
	require.NotNil(t, claimed, "queued apply must be operator-claimable")
	assert.Equal(t, applyID, claimed.ApplyID)
	assert.Equal(t, operations[0].ID, claimed.ID)
	assert.Equal(t, state.ApplyOperation.Pending, claimed.State, "caller sees the pre-claim state")
}

// When API auth is enabled, an authorized write persists an apply attributed to
// the authenticated caller — not the client-supplied Caller. This is the
// storage-backed counterpart to the tier checks: it confirms a write-authorized
// request actually creates a durable apply row, and that a stamp-free break-glass
// write is auditable to the verified identity.
func TestEnqueueAuthorizedApplyRecordsAuthenticatedCaller(t *testing.T) {
	ctx := t.Context()

	dsn := newStorageDatabaseWithSchema(t).DSN
	logger := slog.New(slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelError}))

	db, err := sql.Open("block-mysql", dsn)
	require.NoError(t, err, "failed to open database")
	require.NoError(t, db.PingContext(ctx), "failed to ping database")
	t.Cleanup(func() { utils.CloseAndLog(db) })

	stor := mysqlstore.New(db)

	plan := &storage.Plan{
		PlanIdentifier: "plan-authenticated-caller",
		Database:       "testdb",
		DatabaseType:   storage.DatabaseTypeMySQL,
		Deployment:     "default",
		Target:         "testdb-staging-target",
		Repository:     "octocat/hello-world",
		PullRequest:    1,
		SchemaPath:     "schema/testdb",
		Environment:    "staging",
		Namespaces: map[string]*storage.NamespacePlanData{
			"testdb": {
				Tables: []storage.TableChange{
					{
						Namespace: "testdb",
						Table:     "users",
						DDL:       "ALTER TABLE users ADD COLUMN email varchar(255)",
						Operation: "alter",
					},
				},
			},
		},
		CreatedAt: time.Now(),
	}
	_, err = stor.Plans().Create(ctx, plan)
	require.NoError(t, err, "failed to store plan")

	cfg := &ServerConfig{
		TernDeployments: TernConfig{"default": {"staging": "localhost:9090"}},
	}
	svc := New(stor, cfg, map[string]tern.Client{"default/staging": &mockTernClient{isRemote: true}}, logger)

	// A request from an authenticated caller (as the auth middleware would set)
	// carrying a different, untrusted Caller in the body — the authenticated
	// identity must win.
	authCtx := auth.WithUser(ctx, &auth.User{Subject: "bob@example.com"})
	resp, applyID, err := svc.EnqueueAuthorizedApply(authCtx, ApplyRequest{
		PlanID:      plan.PlanIdentifier,
		Environment: "staging",
		Caller:      "client-supplied-should-be-ignored",
	})
	require.NoError(t, err)
	require.True(t, resp.Accepted)
	require.Positive(t, applyID)

	// Storage confirmation: the apply row is durable, and its caller is the
	// authenticated subject rather than the client-supplied request Caller.
	apply, err := stor.Applies().Get(ctx, applyID)
	require.NoError(t, err)
	require.NotNil(t, apply)
	assert.Equal(t, "bob@example.com", apply.Caller,
		"apply must be attributed to the authenticated caller, not the client-supplied Caller")
}

