func TestParseGitHubTeamPrincipal(t *testing.T) {
	tests := []struct {
		name     string
		value    string
		wantOrg  string
		wantSlug string
		wantErr  string
	}{
		{
			name:     "valid org and team slug",
			value:    "octocat/db-operators",
			wantOrg:  "octocat",
			wantSlug: "db-operators",
		},
		{
			name:    "missing slash",
			value:   "db-operators",
			wantErr: "org/team-slug",
		},
		{
			name:    "extra slash",
			value:   "octocat/platform/db-operators",
			wantErr: "org/team-slug",
		},
		{
			name:    "leading whitespace",
			value:   " octocat/db-operators",
			wantErr: "whitespace",
		},
		{
			name:    "empty org",
			value:   "/db-operators",
			wantErr: "org/team-slug",
		},
		{
			name:    "empty team",
			value:   "octocat/",
			wantErr: "org/team-slug",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			org, slug, err := ParseGitHubTeamPrincipal(tt.value)
