// scopedDenialRequest sends the request to the handler as the given caller and
// returns the response, for asserting on handler-level scoped-write denials.
func scopedDenialRequest(t *testing.T, handler http.HandlerFunc, user *auth.User, method, target, body string) *httptest.ResponseRecorder {
	t.Helper()
	ctx := auth.WithVerifiedUser(t.Context(), user)
	req := httptest.NewRequestWithContext(ctx, method, target, strings.NewReader(body))
	rec := httptest.NewRecorder()
	handler(rec, req)
	return rec
}

// A scoped operator's mutating requests are denied at the handler once the
// target database resolves outside their grant. The 403 names the principals
// that would grant access so a blocked caller knows who to ask.
func TestHandlersEnforceScopedWriteDenials(t *testing.T) {
	logger := slog.New(slog.DiscardHandler)
	operator := &auth.User{Subject: "bob", Groups: []string{"payments-team"}}

	t.Run("plan denies an environment outside the grant", func(t *testing.T) {
		svc := New(&mockStorage{}, scopedWriteConfig(), nil, logger)
		rec := scopedDenialRequest(t, svc.handlePlan, operator, http.MethodPost, "/api/plan",
			`{"database":"payments","environment":"production","type":"mysql","schema_files":{"default":{"files":{"t.sql":"CREATE TABLE t (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY)"}}}}`)

		assert.Equal(t, http.StatusForbidden, rec.Code)
		assert.Contains(t, rec.Body.String(), "staging", "the denial lists the environments the grant allows")
		assert.Contains(t, rec.Body.String(), "schema-admins", "the denial names the groups that could act instead")
	})

	t.Run("apply resolves the database from the stored plan", func(t *testing.T) {
		st := &mockStorageWithPlanLookup{plans: &mockPlanLookupStore{plan: &storage.Plan{
			PlanIdentifier: "plan-1",
			Database:       "payments",
			Environment:    "production",
		}}}
		svc := New(st, scopedWriteConfig(), nil, logger)
		rec := scopedDenialRequest(t, svc.handleApply, operator, http.MethodPost, "/api/apply",
			`{"plan_id":"plan-1","environment":"production"}`)

		assert.Equal(t, http.StatusForbidden, rec.Code)
		assert.Contains(t, rec.Body.String(), "payments", "the denial names the database resolved from the plan")
	})

	t.Run("apply denies when the plan lookup fails: an unresolvable target never authorizes", func(t *testing.T) {
		st := &mockStorageWithPlanLookup{plans: &mockPlanLookupStore{err: assert.AnError}}
		svc := New(st, scopedWriteConfig(), nil, logger)
		rec := scopedDenialRequest(t, svc.handleApply, operator, http.MethodPost, "/api/apply",
			`{"plan_id":"plan-1","environment":"staging"}`)

		assert.Equal(t, http.StatusInternalServerError, rec.Code)
		var resp apitypes.ErrorResponse
		require.NoError(t, json.NewDecoder(rec.Body).Decode(&resp))
		assert.Equal(t, apitypes.ErrCodeStorageError, resp.ErrorCode)
		assert.Contains(t, resp.Error, "failed to get plan plan-1")
		assert.NotContains(t, resp.Error, assert.AnError.Error(), "the storage error stays in the server log")
	})

	t.Run("apply rejects a plan that does not exist at decision time", func(t *testing.T) {
		st := &mockStorageWithPlanLookup{plans: &mockPlanLookupStore{}}
		svc := New(st, scopedWriteConfig(), nil, logger)
		rec := scopedDenialRequest(t, svc.handleApply, operator, http.MethodPost, "/api/apply",
			`{"plan_id":"plan-missing","environment":"staging"}`)

		assert.Equal(t, http.StatusNotFound, rec.Code)
		var resp apitypes.ErrorResponse
		require.NoError(t, json.NewDecoder(rec.Body).Decode(&resp))
		assert.Equal(t, apitypes.ErrCodeNotFound, resp.ErrorCode)
		assert.Contains(t, resp.Error, "plan not found: plan-missing",
			"the authorization decision is bound to a plan that exists when it is made")
	})

	t.Run("control operation resolves the database from the stored apply", func(t *testing.T) {
		st := &mockStorageWithApplyStores{applies: &staticApplyStore{apply: &storage.Apply{
			ApplyIdentifier: "apply-1",
			Database:        "orders",
			Environment:     "staging",
		}}}
		svc := New(st, scopedWriteConfig(), nil, logger)
		rec := scopedDenialRequest(t, svc.handleStop, operator, http.MethodPost, "/api/stop",
			`{"apply_id":"apply-1","environment":"staging"}`)

		assert.Equal(t, http.StatusForbidden, rec.Code)
		assert.Contains(t, rec.Body.String(), "orders", "the denial names the database resolved from the apply")
	})

	t.Run("lock acquire denies a database outside the grant", func(t *testing.T) {
		svc := New(&mockStorage{}, scopedWriteConfig(), nil, logger)
		rec := scopedDenialRequest(t, svc.handleLockAcquire, operator, http.MethodPost, "/api/locks/acquire",
			`{"database":"orders","database_type":"mysql","owner":"bob"}`)

		assert.Equal(t, http.StatusForbidden, rec.Code)
	})

	t.Run("lock release denies a database outside the grant", func(t *testing.T) {
		svc := New(&mockStorage{}, scopedWriteConfig(), nil, logger)
		rec := scopedDenialRequest(t, svc.handleLockRelease, operator, http.MethodDelete, "/api/locks",
			`{"database":"orders","database_type":"mysql","owner":"bob"}`)

		assert.Equal(t, http.StatusForbidden, rec.Code)
		assert.Contains(t, rec.Body.String(), "schema-admins")
	})

	t.Run("settings mutation stays admin-only for scoped operators", func(t *testing.T) {
		svc := New(&mockStorage{}, scopedWriteConfig(), nil, logger)
		rec := scopedDenialRequest(t, svc.handleSettingsSet, operator, http.MethodPost, "/api/settings",
			`{"key":"pause_applies","value":"true"}`)

		assert.Equal(t, http.StatusForbidden, rec.Code)
		assert.Contains(t, rec.Body.String(), "schema-admins")
	})
}

// recordingLockStore records lock mutations so a test can assert whether a
// handler reached the storage layer at all.
type recordingLockStore struct {
	storage.LockStore
	forceReleased bool
	released      bool
}

func (s *recordingLockStore) ForceRelease(context.Context, string, string) error {
	s.forceReleased = true
	return nil
}

func (s *recordingLockStore) Release(context.Context, string, string, string) error {
	s.released = true
	return nil
}

// Force lock release bypasses the ownership check, so it is an administrative
// override: a database operator's grant covers releasing locks their own
// operator group took, but never force-releasing someone else's — for example
// an admin's incident lock holding applies off the database. Only deployment
// write-group members may force.
func TestForceLockReleaseIsAdminOnly(t *testing.T) {
	logger := slog.New(slog.DiscardHandler)
	body := `{"database":"payments","database_type":"mysql","force":true}`

	t.Run("a scoped operator cannot force even on their granted database", func(t *testing.T) {
		locks := &recordingLockStore{}
		svc := New(&mockStorageWithApplyStores{locks: locks}, scopedWriteConfig(), nil, logger)
		operator := &auth.User{Subject: "bob", Groups: []string{"payments-team"}}
		rec := scopedDenialRequest(t, svc.handleLockRelease, operator, http.MethodDelete, "/api/locks", body)

		assert.Equal(t, http.StatusForbidden, rec.Code)
		assert.Contains(t, rec.Body.String(), "schema-admins", "the denial names the write groups that may force")
		assert.False(t, locks.forceReleased, "the handler must not reach storage on a denied force release")
		assert.False(t, locks.released, "a denied force release must not fall through to a normal release")
	})

	t.Run("a deployment write-group member may force", func(t *testing.T) {
		locks := &recordingLockStore{}
		svc := New(&mockStorageWithApplyStores{locks: locks}, scopedWriteConfig(), nil, logger)
		admin := &auth.User{Subject: "alice", Groups: []string{"schema-admins"}}
		rec := scopedDenialRequest(t, svc.handleLockRelease, admin, http.MethodDelete, "/api/locks", body)

		assert.Equal(t, http.StatusOK, rec.Code)
		assert.True(t, locks.forceReleased)
	})

	t.Run("a scoped operator's normal release of their group's lock proceeds", func(t *testing.T) {
		locks := &memoryLockStore{lock: paymentsLock(1, "bob",
			&storage.LockAcquirer{Subject: "bob", OperatorGroups: []string{"payments-team"}})}
		svc := New(&mockStorageWithApplyStores{locks: locks}, scopedWriteConfig(), nil, logger)
		operator := &auth.User{Subject: "bob", Groups: []string{"payments-team"}}
		rec := scopedDenialRequest(t, svc.handleLockRelease, operator, http.MethodDelete, "/api/locks",
			`{"database":"payments","database_type":"mysql","owner":"bob"}`)

		assert.Equal(t, http.StatusOK, rec.Code, rec.Body.String())
		assert.Nil(t, locks.lock, "the ownership-checked release path serves the operator grant")
	})
}

