	sdkmetric "go.opentelemetry.io/otel/sdk/metric"
	"go.opentelemetry.io/otel/sdk/metric/metricdata"
)

// Remote deployment health checks emit one steady-state gauge per configured
// deployment/environment so dashboards can show status even when no schema
// changes are running.
func TestCheckRemoteDeploymentHealthRecordsEachDeployment(t *testing.T) {
	reader := sdkmetric.NewManualReader()
	mp := sdkmetric.NewMeterProvider(sdkmetric.WithReader(reader))
	prevMP := otel.GetMeterProvider()
	otel.SetMeterProvider(mp)
	t.Cleanup(func() {
		otel.SetMeterProvider(prevMP)
		require.NoError(t, mp.Shutdown(t.Context()))
	})

	logger := slog.New(slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelError}))
	config := &ServerConfig{
		TernDeployments: TernConfig{
			"pie":  TernEndpoints{"staging": "pie-staging:9090"},
			"sled": TernEndpoints{"staging": "sled-staging:9090"},
		},
	}
	ternClients := map[string]tern.Client{
		"pie/staging":  &mockTernClient{},
		"sled/staging": &mockTernClient{healthErr: errors.New("connection refused")},
	}
	svc := New(&mockStorage{}, config, ternClients, logger)

	svc.CheckRemoteDeploymentHealth(t.Context())

	var rm metricdata.ResourceMetrics
	require.NoError(t, reader.Collect(t.Context(), &rm))

	healthByDeployment := make(map[string]int64)
	checkStatusByDeployment := make(map[string]string)
	for _, sm := range rm.ScopeMetrics {
		for _, m := range sm.Metrics {
			switch m.Name {
			case "schemabot.remote_deployment.health":
				gauge, ok := m.Data.(metricdata.Gauge[int64])
				require.True(t, ok)
				for _, dp := range gauge.DataPoints {
					deployment, ok := dp.Attributes.Value(attribute.Key("deployment"))
					require.True(t, ok)
					environment, ok := dp.Attributes.Value(attribute.Key("environment"))
					require.True(t, ok)
					assert.Equal(t, "staging", environment.AsString())
					healthByDeployment[deployment.AsString()] = dp.Value
				}
			case "schemabot.remote_deployment.health_checks_total":
				sum, ok := m.Data.(metricdata.Sum[int64])
				require.True(t, ok)
				for _, dp := range sum.DataPoints {
					deployment, ok := dp.Attributes.Value(attribute.Key("deployment"))
					require.True(t, ok)
					status, ok := dp.Attributes.Value(attribute.Key("status"))
					require.True(t, ok)
					checkStatusByDeployment[deployment.AsString()] = status.AsString()
				}
			}
		}
	}

	assert.Equal(t, map[string]int64{"pie": 1, "sled": 0}, healthByDeployment)
	assert.Equal(t, map[string]string{"pie": "success", "sled": "error"}, checkStatusByDeployment)
}

func TestStartRemoteDeploymentHealthMonitorSkipsEmptyConfig(t *testing.T) {
	logger := slog.New(slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelError}))
	svc := New(&mockStorage{}, &ServerConfig{}, nil, logger)

	svc.StartRemoteDeploymentHealthMonitor(t.Context())

	svc.remoteHealthMu.Lock()
	defer svc.remoteHealthMu.Unlock()
	assert.Nil(t, svc.remoteHealthCancel)
}

package api

import (
	"errors"
	"log/slog"
	"os"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	ternv1 "github.com/block/schemabot/pkg/proto/ternv1"
	"github.com/block/schemabot/pkg/routing"
	"github.com/block/schemabot/pkg/storage"
	"github.com/block/schemabot/pkg/tern"
)

// twoDeploymentService builds a testapp/production database that fans out to two
// deployments (eu primary, us), each backed by its own registered mock tern
// client, so PlanDeploymentDiffs can be exercised without live databases.
func twoDeploymentService(t *testing.T, eu, us *mockTernClient) *Service {
	t.Helper()
	cfg := &ServerConfig{
		Databases: map[string]DatabaseConfig{
			"testapp": {
				Type: storage.DatabaseTypeMySQL,
				Environments: map[string]EnvironmentConfig{
					"production": {
						Deployments: map[string]DeploymentTarget{
							"eu": {Target: "testapp"},
							"us": {Target: "testapp"},
						},
						DeploymentOrder: []string{"eu", "us"},
					},
				},
			},
		},
	}
	logger := slog.New(slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelError}))
	return New(&mockStorage{}, cfg, map[string]tern.Client{
		"eu/production": eu,
		"us/production": us,
	}, logger)
}

// productionMember names one rollout member of the testapp/production set. Both
// deployments address the same target, so the deployment half is what
// distinguishes them here.
func productionMember(deployment string) routing.ExecutionTarget {
	return routing.ExecutionTarget{Deployment: deployment, Target: "testapp"}
}

// productionTargets resolves the testapp/production deployment set the producer
// tests exercise, so each PlanDeploymentDiffs call is given the same resolved
// targets the rollup would pass in.
func productionTargets(t *testing.T, svc *Service) []routing.ExecutionTarget {
	t.Helper()
	targets, err := svc.config.ResolveDatabaseTargets("testapp", "production")
	require.NoError(t, err)
	return targets
}

func planDiffReq(t *testing.T) PlanRequest {
	t.Helper()
	return PlanRequest{
		Database:    "testapp",
		Environment: "production",
		Type:        storage.DatabaseTypeMySQL,
		SchemaFiles: map[string]*ternv1.SchemaFiles{
			"testapp": {Files: map[string]string{"users.sql": "CREATE TABLE `users` (id bigint primary key)"}},
		},
	}
}

func alterUsersDiff(ddl string) *ternv1.PlanDiffResponse {
	return &ternv1.PlanDiffResponse{
		Engine: ternv1.Engine_ENGINE_SPIRIT,
		Changes: []*ternv1.SchemaChange{{
			Namespace: "testapp",
			TableChanges: []*ternv1.TableChange{{
				TableName:  "users",
				ChangeType: ternv1.ChangeType_CHANGE_TYPE_ALTER,
				Ddl:        ddl,
				Namespace:  "testapp",
			}},
		}},
	}
}

// With the primary plan supplied, the primary member of the rollup is
// the primary plan itself (no redundant live-schema read of the primary), and
// only the non-primary deployments run PlanDiff. Results stay in rollout order.
func TestPlanDeploymentDiffs_PrimaryReusesItsOwnPlan(t *testing.T) {
	eu := &mockTernClient{}
	us := &mockTernClient{planDiffResp: alterUsersDiff("ALTER TABLE `users` ADD COLUMN `email` varchar(255)")}
	svc := twoDeploymentService(t, eu, us)

	primaryPlan := &ternv1.PlanResponse{
		PlanId: "plan_eu",
		Engine: ternv1.Engine_ENGINE_SPIRIT,
		Changes: []*ternv1.SchemaChange{{
			Namespace: "testapp",
			TableChanges: []*ternv1.TableChange{{
				TableName:  "users",
				ChangeType: ternv1.ChangeType_CHANGE_TYPE_ALTER,
				Ddl:        "ALTER TABLE `users` ADD COLUMN `email` varchar(255)",
				Namespace:  "testapp",
			}},
		}},
	}

	results, err := svc.PlanDeploymentDiffs(t.Context(), planDiffReq(t), primaryPlan, productionMember("eu"), productionTargets(t, svc))
	require.NoError(t, err)
	require.Len(t, results, 2)

	assert.Equal(t, "eu", results[0].Deployment)
	assert.Nil(t, eu.planDiffReq, "primary must reuse the primary target's plan, not re-diff")
	require.NoError(t, results[0].Err)
	assert.Equal(t, primaryPlan.Changes, results[0].Changes)

	assert.Equal(t, "us", results[1].Deployment)
	require.NotNil(t, us.planDiffReq, "non-primary deployment must be diffed")
	assert.Equal(t, "testapp", us.planDiffReq.Target)
	require.NoError(t, results[1].Err)
	require.Len(t, results[1].Changes, 1)
	assert.Equal(t, "ALTER TABLE `users` ADD COLUMN `email` varchar(255)", results[1].Changes[0].TableChanges[0].Ddl)
}

// Without the primary plan, every deployment (including the primary) is diffed
// with PlanDiff.
func TestPlanDeploymentDiffs_DiffsAllDeploymentsWhenNoPrimary(t *testing.T) {
	eu := &mockTernClient{planDiffResp: alterUsersDiff("ALTER TABLE `users` ADD COLUMN `email` varchar(255)")}
	us := &mockTernClient{planDiffResp: alterUsersDiff("ALTER TABLE `users` ADD COLUMN `email` varchar(255)")}
	svc := twoDeploymentService(t, eu, us)

	results, err := svc.PlanDeploymentDiffs(t.Context(), planDiffReq(t), nil, routing.ExecutionTarget{}, productionTargets(t, svc))
	require.NoError(t, err)
	require.Len(t, results, 2)

	require.NotNil(t, eu.planDiffReq, "primary must be diffed when no primary target's plan is supplied")
	require.NotNil(t, us.planDiffReq)
	require.NoError(t, results[0].Err)
	require.NoError(t, results[1].Err)
}

// One deployment failing to diff must not abort the rollup or hide the others:
// its error is captured per result (so the rollup can fail closed on it) while
// the healthy deployment still returns its changes.
func TestPlanDeploymentDiffs_PerDeploymentErrorIsCaptured(t *testing.T) {
	eu := &mockTernClient{planDiffResp: alterUsersDiff("ALTER TABLE `users` ADD COLUMN `email` varchar(255)")}
	us := &mockTernClient{planDiffErr: errors.New("deployment unreachable")}
	svc := twoDeploymentService(t, eu, us)

	results, err := svc.PlanDeploymentDiffs(t.Context(), planDiffReq(t), nil, routing.ExecutionTarget{}, productionTargets(t, svc))
	require.NoError(t, err, "a single deployment failure must not abort the rollup")
	require.Len(t, results, 2)

	require.NoError(t, results[0].Err)
	require.Len(t, results[0].Changes, 1)

	require.Error(t, results[1].Err)
	assert.Contains(t, results[1].Err.Error(), "deployment unreachable")
	assert.Nil(t, results[1].Changes)
}

// A deployment's PlanDiff can carry per-shard plans, and the deployment and
// shard axes are orthogonal: the producer iterates deployments while each
// deployment's single diff retains its full per-shard set. This guards that the
// producer copies resp.Shards through, so per-shard drift within a deployment
// stays visible to the rollup rather than being flattened away.
func TestPlanDeploymentDiffs_PreservesShards(t *testing.T) {
	usShards := &ternv1.PlanDiffResponse{
		Engine: ternv1.Engine_ENGINE_SPIRIT,
		Shards: []*ternv1.ShardPlan{
			{
				Shard:     "-80",
				Namespace: "testapp",
				Changes: []*ternv1.TableChange{{
					TableName:  "users",
					ChangeType: ternv1.ChangeType_CHANGE_TYPE_ALTER,
					Ddl:        "ALTER TABLE `users` ADD COLUMN `email` varchar(255)",
					Namespace:  "testapp",
				}},
			},
			{
				Shard:     "80-",
				Namespace: "testapp",
				Changes: []*ternv1.TableChange{{
					TableName:  "users",
					ChangeType: ternv1.ChangeType_CHANGE_TYPE_ALTER,
					Ddl:        "ALTER TABLE `users` ADD COLUMN `phone` varchar(32)",
					Namespace:  "testapp",
				}},
			},
		},
	}
	eu := &mockTernClient{}
	us := &mockTernClient{planDiffResp: usShards}
	svc := twoDeploymentService(t, eu, us)

	primaryPlan := &ternv1.PlanResponse{
		PlanId: "plan_eu",
		Engine: ternv1.Engine_ENGINE_SPIRIT,
		Shards: []*ternv1.ShardPlan{{
			Shard:     "0",
			Namespace: "testapp",
			Changes: []*ternv1.TableChange{{
				TableName:  "users",
				ChangeType: ternv1.ChangeType_CHANGE_TYPE_ALTER,
				Ddl:        "ALTER TABLE `users` ADD COLUMN `email` varchar(255)",
				Namespace:  "testapp",
			}},
		}},
	}

	results, err := svc.PlanDeploymentDiffs(t.Context(), planDiffReq(t), primaryPlan, productionMember("eu"), productionTargets(t, svc))
	require.NoError(t, err)
	require.Len(t, results, 2)

	// The primary reuses the primary plan's shard set verbatim.
	require.NoError(t, results[0].Err)
	assert.Equal(t, primaryPlan.Shards, results[0].Shards)

	// The non-primary deployment's full two-shard set survives the producer.
	require.NoError(t, results[1].Err)
	require.Len(t, results[1].Shards, 2)
	assert.Equal(t, "-80", results[1].Shards[0].Shard)
	assert.Equal(t, "ALTER TABLE `users` ADD COLUMN `email` varchar(255)", results[1].Shards[0].Changes[0].Ddl)
	assert.Equal(t, "80-", results[1].Shards[1].Shard)
	assert.Equal(t, "ALTER TABLE `users` ADD COLUMN `phone` varchar(32)", results[1].Shards[1].Changes[0].Ddl)
}

// If the primary plan's origin deployment no longer matches rollout index 0
// (e.g. deployment_order changed between plan and rollup), reusing that plan as
// the primary baseline would compare deployments against a plan built for a
// different deployment. The producer must fail closed instead.
func TestPlanDeploymentDiffs_PrimaryDeploymentMismatchFailsClosed(t *testing.T) {
	eu := &mockTernClient{}
	us := &mockTernClient{planDiffResp: alterUsersDiff("ALTER TABLE `users` ADD COLUMN `email` varchar(255)")}
	svc := twoDeploymentService(t, eu, us)

	primaryPlan := &ternv1.PlanResponse{PlanId: "plan_eu", Engine: ternv1.Engine_ENGINE_SPIRIT}

	// targets[0] is "eu", but the primary plan was created against "us".
	_, err := svc.PlanDeploymentDiffs(t.Context(), planDiffReq(t), primaryPlan, productionMember("us"), productionTargets(t, svc))
	require.Error(t, err)
	assert.Contains(t, err.Error(), "primary invariant violated")
	assert.Nil(t, eu.planDiffReq, "must fail before diffing any deployment")
	assert.Nil(t, us.planDiffReq)
}

// The primary plan supplied without its origin deployment cannot be verified
// against rollout index 0, so the producer fails closed rather than trusting
// the positional assumption blindly.
func TestPlanDeploymentDiffs_PrimaryPlanWithoutOriginFailsClosed(t *testing.T) {
	eu := &mockTernClient{}
	us := &mockTernClient{planDiffResp: alterUsersDiff("ALTER TABLE `users` ADD COLUMN `email` varchar(255)")}
	svc := twoDeploymentService(t, eu, us)

	primaryPlan := &ternv1.PlanResponse{PlanId: "plan_eu", Engine: ternv1.Engine_ENGINE_SPIRIT}

	_, err := svc.PlanDeploymentDiffs(t.Context(), planDiffReq(t), primaryPlan, routing.ExecutionTarget{}, productionTargets(t, svc))
	require.Error(t, err)
	assert.Contains(t, err.Error(), "no origin deployment")
}

// Called with no resolved targets the producer fails closed rather than
// returning an empty result that a caller could mistake for agreement.
func TestPlanDeploymentDiffs_NoTargetsError(t *testing.T) {
	svc := twoDeploymentService(t, &mockTernClient{}, &mockTernClient{})

	_, err := svc.PlanDeploymentDiffs(t.Context(), planDiffReq(t), nil, routing.ExecutionTarget{}, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "no deployment targets")
}

